      if (cheap[0]) { if (deck.length >= 8) deck.splice(deck.findIndex(x => !isSpell(x) && !WIN_CARDS.has(x) && !(hitsAir(x) && deck.filter(hitsAir).length <= 3)), 1); add(cheap[0]); }
