    const late = s.phase === 'overtime' || s.phase === 'sudden' || (s.double && s.timeLeft < 45);
    const behind = s.crowns[me] < s.crowns[enemy] || ((s.phase === 'overtime' || s.phase === 'sudden') && S.lowestTower(s, me) < S.lowestTower(s, enemy));
